<script lang="ts">import type { ConnectionCheck, Resource } from '../../lib/api'; import { resourceEndpointFor } from './resourceCatalog'; export let resource: Resource; export let resourceCheck: ConnectionCheck|null|undefined; export let mcpServerEndpoint=''; export let formatDate:(v:string)=>string; const tools=['kafka_health','kafka_brokers','kafka_topics','kafka_consumer_groups','kafka_consumer_lag','kafka_cluster_info','kafka_topic_partitions']; $: agent=String(resource.subtype??'').toLowerCase()==='agent'; $: status=resourceCheck?.status==='succeeded'?`正常·${resourceCheck.latency_ms}ms`:resourceCheck?.status==='failed'?'异常':'尚未测试';</script>
<div class="provider-resource-details postgres-resource-details"><div class="provider-resource-meta"><div><span>接入方式</span><strong class:agent>{agent?'Agent · MCP 代理':'Direct'}</strong></div><div><span>连接端点</span><strong>{agent?mcpServerEndpoint||'关联 MCPServer':resourceEndpointFor(resource)}</strong></div><div><span>Broker 数量</span><strong>{Array.isArray(resource.config?.brokers)?resource.config.brokers.length:0}</strong></div><div><span>最新更新</span><strong>{formatDate(resource.updated_at)}</strong></div><div><span>状态</span><strong>{status} ({resource.status==='active'?'已启用':'已停用'})</strong></div></div><div class="provider-resource-models mcp-resource-tools"><div class="provider-resource-models-heading"><strong>工具列表</strong><span>{tools.length} 个</span></div>{#each tools as tool}<div class="provider-resource-model-row mcp-resource-tool-row"><div><strong>{tool}</strong></div></div>{/each}</div></div>
